import json
import csv
import re
import os


def parse_wkt_point(wkt_str):
    """Parse a WKT Point string like 'Point(lon lat)' -> (lat, lon)"""
    if not wkt_str or not isinstance(wkt_str, str):
        return None, None
    match = re.match(
        r'\s*POINT\s*\(\s*(-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)\s+(-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)\s*\)\s*',
        wkt_str,
        re.IGNORECASE
    )
    if match:
        lon = float(match.group(1))
        lat = float(match.group(2))
        return lat, lon
    return None, None


def extract_label(item):
    """Extract label from various possible Wikidata JSON formats."""
    # Try itemLabel first
    if 'itemLabel' in item and item['itemLabel']:
        return str(item['itemLabel'])

    # Try labels dict (standard Wikidata API format)
    labels = item.get('labels', {})
    if isinstance(labels, dict):
        # Try 'en' first
        en = labels.get('en')
        if isinstance(en, dict) and en.get('value'):
            return str(en['value'])
        elif isinstance(en, str) and en:
            return en
        # Try any available label
        for lang_val in labels.values():
            if isinstance(lang_val, dict) and lang_val.get('value'):
                return str(lang_val['value'])
            elif isinstance(lang_val, str) and lang_val:
                return lang_val

    # Try 'label' field
    if 'label' in item and item['label']:
        return str(item['label'])

    return None


def extract_coordinates(item):
    """Extract coordinates as (lat, lon) from various possible formats."""
    # Try 'coord', 'coordinate', 'coordinates', 'geo' direct fields
    for key in ['coord', 'coordinate', 'coordinates', 'geo', 'geom']:
        if key in item:
            val = item[key]
            if isinstance(val, str):
                lat, lon = parse_wkt_point(val)
                if lat is not None:
                    return lat, lon
            elif isinstance(val, dict):
                lat = val.get('lat')
                lon = val.get('lon')
                if lat is not None and lon is not None:
                    return float(lat), float(lon)

    # Try P625 (coordinate location) in claims
    claims = item.get('claims', {})
    if isinstance(claims, dict):
        p625 = claims.get('P625', [])
        if isinstance(p625, dict):
            p625 = [p625]
        if p625:
            for claim in p625:
                if not isinstance(claim, dict):
                    continue
                mainsnak = claim.get('mainsnak', {})
                datavalue = mainsnak.get('datavalue', {})
                value = datavalue.get('value')

                if isinstance(value, str):
                    lat, lon = parse_wkt_point(value)
                    if lat is not None:
                        return lat, lon
                elif isinstance(value, dict):
                    lat = value.get('lat')
                    lon = value.get('lon')
                    if lat is not None and lon is not None:
                        return float(lat), float(lon)

    # Try 'snaks' format (alternative Wikidata structure)
    snaks = item.get('snaks', {})
    if isinstance(snaks, dict):
        p625_snaks = snaks.get('P625', [])
        if isinstance(p625_snaks, dict):
            p625_snaks = [p625_snaks]
        if p625_snaks:
            for snak in p625_snaks:
                if not isinstance(snak, dict):
                    continue
                datavalue = snak.get('datavalue', {})
                value = datavalue.get('value')
                if isinstance(value, str):
                    lat, lon = parse_wkt_point(value)
                    if lat is not None:
                        return lat, lon
                elif isinstance(value, dict):
                    lat = value.get('lat')
                    lon = value.get('lon')
                    if lat is not None and lon is not None:
                        return float(lat), float(lon)

    return None, None


def extract_poi_type(item):
    """Extract POI type from various possible formats."""
    # Direct fields
    for key in ['poi_type', 'poiType', 'type', 'category', 'instanceOf', 'instance_of']:
        if key in item:
            val = item[key]
            if isinstance(val, str) and val:
                return val
            elif isinstance(val, dict):
                labels = val.get('labels', {})
                if isinstance(labels, dict):
                    en = labels.get('en')
                    if isinstance(en, dict) and en.get('value'):
                        return str(en['value'])
                    elif isinstance(en, str) and en:
                        return en
                qid = val.get('id', '')
                if qid:
                    return qid
            elif isinstance(val, list) and val:
                first = val[0]
                if isinstance(first, str):
                    return first
                elif isinstance(first, dict):
                    labels = first.get('labels', {})
                    if isinstance(labels, dict):
                        en = labels.get('en')
                        if isinstance(en, dict) and en.get('value'):
                            return str(en['value'])
                    return first.get('id', '')

    # Try P31 (instance of) in claims
    claims = item.get('claims', {})
    if isinstance(claims, dict):
        p31 = claims.get('P31', [])
        if isinstance(p31, dict):
            p31 = [p31]
        if p31:
            for claim in p31:
                if not isinstance(claim, dict):
                    continue
                mainsnak = claim.get('mainsnak', {})
                datavalue = mainsnak.get('datavalue', {})
                value = datavalue.get('value', {})
                if isinstance(value, dict):
                    qid = value.get('id', '')
                    if qid:
                        return qid
                    # Try to get label from the value
                    labels = value.get('labels', {})
                    if isinstance(labels, dict):
                        en = labels.get('en')
                        if isinstance(en, dict) and en.get('value'):
                            return str(en['value'])

    # Try P106 (occupation) or other type-related properties
    for prop in ['P106', 'P178', 'P279']:
        claims = item.get('claims', {})
        if isinstance(claims, dict):
            claims_val = claims.get(prop, [])
            if isinstance(claims_val, dict):
                claims_val = [claims_val]
            if claims_val:
                for claim in claims_val:
                    if not isinstance(claim, dict):
                        continue
                    mainsnak = claim.get('mainsnak', {})
                    datavalue = mainsnak.get('datavalue', {})
                    value = datavalue.get('value', {})
                    if isinstance(value, dict):
                        qid = value.get('id', '')
                        if qid:
                            return qid

    return ''


def format_coord(value):
    """Format a coordinate value preserving its precision."""
    if value is None:
        return ''
    # Use repr-like formatting to preserve precision
    # Remove trailing zeros but keep at least one decimal
    s = str(float(value))
    # For very precise values, ensure we don't lose digits
    if '.' in s:
        # Keep as is - Python's str() for float gives shortest round-trip
        pass
    return s


def main():
    input_path = 'inputs/wikidata/wikidata_pois_sample.json'
    output_path = 'outputs/t08_pois_clean.csv'

    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    with open(input_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Handle different top-level structures to get a list of items
    items = []
    if isinstance(data, list):
        items = data
    elif isinstance(data, dict):
        if 'items' in data:
            items_val = data['items']
            if isinstance(items_val, dict):
                items = list(items_val.values())
            elif isinstance(items_val, list):
                items = items_val
        elif 'pages' in data:
            pages = data['pages']
            if isinstance(pages, dict):
                items = list(pages.values())
            elif isinstance(pages, list):
                items = pages
        elif 'results' in data:
            items = data['results']
            if isinstance(items, dict):
                items = list(items.values())
        else:
            # Maybe the top-level dict is a single item
            items = [data]

    seen_qids = set()
    rows = []

    for item in items:
        if not isinstance(item, dict):
            continue

        # Extract qid
        qid = item.get('id') or item.get('qid') or item.get('QID') or item.get('Q') or ''
        if not qid:
            # Try nested structures
            if 'id' in item and isinstance(item['id'], dict):
                qid = item['id'].get('value', '')
            else:
                continue
        qid = str(qid)

        if not qid:
            continue

        # Deduplicate by qid
        if qid in seen_qids:
            continue
        seen_qids.add(qid)

        # Extract label
        label = extract_label(item)
        if not label or not str(label).strip():
            label = qid  # Deterministic fallback

        # Extract and validate coordinates
        lat, lon = extract_coordinates(item)
        if lat is None or lon is None:
            continue

        # Validate ranges
        if not (-90.0 <= lat <= 90.0):
            continue
        if not (-180.0 <= lon <= 180.0):
            continue

        # Extract POI type
        poi_type = extract_poi_type(item)
        if poi_type is None:
            poi_type = ''

        rows.append({
            'qid': qid,
            'label': label,
            'poi_type': poi_type,
            'latitude': format_coord(lat),
            'longitude': format_coord(lon),
            'source': 'wikidata'
        })

    # Write RFC 4180 compliant CSV
    fieldnames = ['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source']
    with open(output_path, 'w', encoding='utf-8', newline='') as f:
        writer = csv.DictWriter(
            f,
            fieldnames=fieldnames,
            quoting=csv.QUOTE_MINIMAL,
            lineterminator='\r\n'
        )
        writer.writeheader()
        for row in rows:
            writer.writerow(row)


if __name__ == '__main__':
    main()
