                    if isinstance(labels, dict):
                        en = labels.get('en')
                        if isinstance(en, dict) and en.get('value'):
                            return str(en['value'])

    # Try P106 (occupation) or other type-related properties
    for prop in ['P106', 'P178', 'P279']:
        claims = item.get('claims', {})
        if isinstance(claims, dict):
            claims_val = claims.get(prop, [])
            if isinstance(claims_val, dict):
                claims_val = [claims_val]
            if claims_val:
                for claim in claims_val:
                    if not isinstance(claim, dict):
                        continue
                    mainsnak = claim.get('mainsnak', {})
                    datavalue = mainsnak.get('datavalue', {})
                    value = datavalue.get('value', {})
                    if isinstance(value, dict):
                        qid = value.get('id', '')
                        if qid:
                            return qid

    return ''


def format_coord(value):
    """Format a coordinate value preserving its precision."""
    if value is None:
        return ''
    # Use repr-like formatting to preserve precision
    # Remove trailing zeros but keep at least one decimal
    s = str(float(value))
    # For very precise values, ensure we don't lose digits
    if '.' in s:
        # Keep as is - Python's str() for float gives shortest round-trip
        pass
    return s


def main():
    input_path = 'inputs/wikidata/wikidata_pois_sample.json'
    output_path = 'outputs/t08_pois_clean.csv'

    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    with open(input_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Handle different top-level structures to get a list of items
    items = []
    if isinstance(data, list):
        items = data
    elif isinstance(data, dict):
        if 'items' in data:
            items_val = data['items']
            if isinstance(items_val, dict):
                items = list(items_val.values())
            elif isinstance(items_val, list):
                items = items_val
        elif 'pages' in data:
            pages = data['pages']
            if isinstance(pages, dict):
                items = list(pages.values())
            elif isinstance(pages, list):
                items = pages
        elif 'results' in data:
            items = data['results']
            if isinstance(items, dict):
                items = list(items.values())
        else:
            # Maybe the top-level dict is a single item
            items = [data]

    seen_qids = set()
    rows = []

    for item in items:
        if not isinstance(item, dict):
            continue

        # Extract qid
        qid = item.get('id') or item.get('qid') or item.get('QID') or item.get('Q') or ''
        if not qid:
            # Try nested structures
            if 'id' in item and isinstance(item['id'], dict):
                qid = item['id'].get('value', '')
            else:
                continue
        qid = str(qid)

        if not qid:
            continue

        # Deduplicate by qid
        if qid in seen_qids:
            continue
        seen_qids.add(qid)

        # Extract label
        label = extract_label(item)
        if not label or not str(label).strip():
            label = qid  # Deterministic fallback

        # Extract and validate coordinates
        lat, lon = extract_coordinates(item)
        if lat is None or lon is None:
            continue

        # Validate ranges
        if not (-90.0 <= lat <= 90.0):
            continue
        if not (-180.0 <= lon <= 180.0):
            continue

        # Extract POI type
        poi_type = extract_poi_type(item)
        if poi_type is None:
            poi_type = ''

        rows.append({
            'qid': qid,
            'label': label,
            'poi_type': poi_type,
            'latitude': format_coord(lat),
            'longitude': format_coord(lon),
            'source': 'wikidata'
        })

    # Write RFC 4180 compliant CSV
    fieldnames = ['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source']
    with open(output_path, 'w', encoding='utf-8', newline='') as f:
        writer = csv.DictWriter(
            f,
            fieldnames=fieldnames,
            quoting=csv.QUOTE_MINIMAL,
            lineterminator='\r\n'
        )
        writer.writeheader()
        for row in rows:
            writer.writerow(row)


if __name__ == '__main__':
    main()
